import{_ as a,o as n,c as p,a3 as t}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"Learning Primitive Embodied World Models: Towards Scalable Robotic Learning","description":"","frontmatter":{"title":"Learning Primitive Embodied World Models: Towards Scalable Robotic Learning","arxiv":"2508.20840","date":"2025-08-28","authors":"Qiao Sun, Liujia Yang, Wei Tang, Wei Huang, Kaixin Xu, Yongchao Chen, Mingyu Liu, Jiange Yang, et al.","categories":"cs.RO, cs.AI, cs.MM","topics":"具身世界模型, 动作基元, 组合泛化","outline":[2,2]},"headers":[],"relativePath":"papers/2508.20840.md","filePath":"papers/2508.20840.md","lastUpdated":null}'),l={name:"papers/2508.20840.md"};function e(i,s,m,r,c,h){return n(),p("div",null,[...s[0]||(s[0]=[t('<h1 id="learning-primitive-embodied-world-models-towards-scalable-robotic-learning" tabindex="-1">Learning Primitive Embodied World Models: Towards Scalable Robotic Learning <a class="header-anchor" href="#learning-primitive-embodied-world-models-towards-scalable-robotic-learning" aria-label="Permalink to &quot;Learning Primitive Embodied World Models: Towards Scalable Robotic Learning&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2508.20840" target="_blank" rel="noreferrer">2508.20840</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-08-28</td></tr><tr><td><strong>作者</strong></td><td>Qiao Sun, Liujia Yang, Wei Tang, Wei Huang, Kaixin Xu, Yongchao Chen, Mingyu Liu, Jiange Yang, et al.（Shanghai AI Lab 等）</td></tr><tr><td><strong>分类</strong></td><td>cs.RO, cs.AI, cs.MM</td></tr><tr><td><strong>一句话</strong></td><td>把具身视频世界模型的预测窗口压到「一条语言指令对应的一个原子动作」（约 2 秒 / 32 帧），用起止点热力图做空间接地、VLM 规划器串接原语，从而在 1.4B 小模型上直接抽出可执行的 6-DoF 轨迹。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/physics-aware">物理感知视频生成</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>把视频生成当作具身策略的主流做法是：给一条语言指令，生成一段未来 rollout，再从中反解动作。这条路线的吸引力在于可解释、可迁移、表示统一。但它有一个默认前提——预测窗口越长，规划越好。论文直接质疑这个前提。</p><p>理由是数据的结构。具身交互数据高维、稀疏、采集昂贵；预测窗口一拉长，语言概念与低层动作之间的对齐就越发病态：一句「把杯子放进抽屉」对应的 10 秒视频里，哪一帧对应「打开」、哪一帧对应「放入」，监督信号根本不提供答案。窗口越长，模型越只能学到粗粒度的语义关联，越难支撑精确控制。论文给出的观察很朴素：<strong>具身数据的多样性远远超过可能的原子动作空间</strong>。既然如此，就应该在原子动作这个尺度上组织数据和模型。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>视频即世界模型</strong>：UniPi、RoboDreamer、TesserAct（4DWM）等把策略学习转成视频生成，普遍走大 DiT + 长 horizon 的路子，计算昂贵、无法实时；层次化的变体（ManipGen、RoboDreamer）改善了结构，但作者指出它们仍有误差传播与跨模态对齐僵化的问题，且都没有把视觉语言推理、规划、空间接地整合进一个零样本执行框架。</p><p><strong>端到端 VLA</strong>：RT-2、OpenVLA 直接把多模态输入映射到动作，短程任务上有效，但长程泛化与跨域迁移弱，且几乎都依赖 in-domain 演示。论文的实验里 OpenVLA 零样本在三个真实任务上全部 0/20，是这一点的直接体现。</p><p><strong>数据集</strong>：OpenX-Embodiment 规模大但扩展昂贵、语义与形态多样性有限；RH20T-p 加了原语标注但引入噪声；RLBench、CALVIN 这类仿真环境可控却不真实。前人不是没意识到原语的价值，而是原语标注要么靠固定语法（不灵活），要么靠人工（不可扩展）。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>从三个已知观察出发。第一，扩散模型有很强的隐式组合能力——「宇航员骑马」这种训练集里不共现的组合可以被合成出来，说明它学到的是可重组的因子而非样本记忆。第二，长程具身任务在人类语言里天然是可分解的：任何一条长指令都能写成若干条短指令的序列。第三，一次长程演示如果按原语切开，可以变成多条带标注的样本——数据量凭空放大数倍。</p><p>把三者叠在一起，结论就出来了：如果把生成窗口限制在「一条语言指令 = 一个语义不可分的动作单元」，那么 (a) 语言与视觉的对齐变得细粒度且明确，(b) 建模复杂度下降，小模型就够，(c) 采集效率提升，(d) 推理延迟下降。剩下的问题是长程怎么办——交给一个 VLM 规划器把原语串起来，让世界模型退回「小脑」的角色，负责快速反应式的动态建模，「大脑皮层」的规划交给 VLM。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>长程视频预测之所以难，不是因为模型不够大，而是因为一条长指令与一段长视频之间没有可对齐的中间结构。把窗口切到语义原子的尺度，语言与像素就一一对上了，扩散模型此时既能吃下细粒度监督，又能靠自身的组合能力把没见过的（动作，物体）配对泛化出来；长程能力则由外部规划器通过串接原语显式提供，而不是指望单个模型在一次前向里全包。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以「把杯子拿起来放进抽屉」为例：</p><ol><li><strong>规划</strong>：VLM 规划器（冻结的 Qwen2.5-VL-7B-Instruct + Chain-of-LoRA 结构，含 Reasoner、Planner LoRA-P、Grounder LoRA-G、Verifier）读入指令与当前观测帧，输出原语序列 <code>pick(cup) → move-to(upper drawer) → open(upper drawer) → place(cup)</code>，Verifier 判定计划是否可执行。</li><li><strong>空间接地</strong>：对每个原语，Grounder 给出夹爪的起点 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 与终点 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 的像素坐标，做高斯模糊得到热力图，取差 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0813em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">s</span><span class="mrel mtight">→</span><span class="mord mathnormal mtight" style="margin-right:0.0359em;">g</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0813em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">g</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0813em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">s</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 作为空间引导信号（SGG）。</li><li><strong>生成</strong>：以当前帧 + 原语文本 + 热力图为条件，DynamiCrafter（1.4B）生成 32 帧短 rollout。训练时观测包含<strong>整条机械臂</strong>而非只裁剪末端，使模型隐式学到可达性、关节限位这类软物理约束。</li><li><strong>动作提取</strong>：对生成视频跑 Gen6D（零样本 6D 位姿估计），结合首帧深度做尺度校正，得到末端 6-DoF 轨迹并映射到笛卡尔控制空间执行。二值夹爪开合不走视频生成，直接符号化执行。</li><li><strong>闭环</strong>：执行后重新观测，把最新帧回灌给规划器，进入下一个原语。可修正漂移与外部扰动。</li></ol><p><strong>数据</strong>：7,326 条仿真原语 + 11,465 条真实原语，FR3 Franka 臂 + 5 台同步相机（2 台 Realsense + 3 台 Femto Bolt），遥操作设备按键在线打原语边界，平均每次会话切出 5.8 条原语，配合多视角并行，采集效率最高提升约 29×；标注先人工做 10%，再微调 Qwen2.5-VL-7B 自动标注其余，标注界面五视角共用一条描述，标注量再降 5×。</p><p><strong>训练</strong>：三阶段微调——仿真预微调（高学习率、早停在「动作趋势合理」处）、真实与仿真 1:1 混合（学习率减半）、真实 80% / 仿真 20% 精修并引入 Visual Detail Guidance（把原始输入图拼到每帧初始噪声上）。最后按 Self-Forcing 做因果蒸馏，每个 4 帧 chunk 只需 4 步去噪，论文报告可达 12 FPS 的在线预测。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>论文给了一个把「原语组合足够表达一切轨迹」形式化的结论。设状态空间 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7224em;vertical-align:-0.0391em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">⊂</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8491em;"></span><span class="mord"><span class="mord mathbb">R</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8491em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">d</span></span></span></span></span></span></span></span></span></span></span> 紧致，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathcal">M</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord mathnormal" style="margin-right:0.046em;">ξ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">C</span><span class="mopen">([</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mclose">]</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span><span class="mclose">)}</span></span></span></span> 是有限时长连续轨迹空间，配一致度量</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal">d</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">∞</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.046em;">ξ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.046em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.046em;">ξ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.046em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.9104em;vertical-align:-1.1604em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.4306em;"><span style="top:-2.1146em;margin-left:0em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mrel mtight">∈</span><span class="mopen mtight">[</span><span class="mord mtight">0</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span><span class="mclose mtight">]</span></span></span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span><span class="mop">sup</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.1604em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">∥</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.046em;">ξ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.046em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.046em;">ξ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.046em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mord">∥</span></span></span></span></span></p><p><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathcal" style="margin-right:0.0583em;">C</span><span class="mopen">(</span><span class="mord mathcal" style="margin-right:0.2542em;">T</span><span class="mclose">)</span></span></span></span> 表示由原语模板集 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.2542em;">T</span></span></span></span> 的有限组合可得到的全部轨迹。<strong>Theorem A.4（原语组合的稠密性）</strong>：在语义接地、时间局部性、组合可执行三条假设下，对任意 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.046em;">ξ</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6887em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">∗</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathcal">M</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span><span class="mclose">)</span></span></span></span> 与任意 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5782em;vertical-align:-0.0391em;"></span><span class="mord mathnormal">ϵ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&gt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span>，存在组合轨迹 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.046em;">ξ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathcal" style="margin-right:0.0583em;">C</span><span class="mopen">(</span><span class="mord mathcal" style="margin-right:0.2542em;">T</span><span class="mclose">)</span></span></span></span> 使 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal">d</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">∞</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.046em;">ξ</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.046em;">ξ</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6887em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">∗</span></span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">ϵ</span></span></span></span>。</p><p>证明思路很直接：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.046em;">ξ</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6887em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">∗</span></span></span></span></span></span></span></span></span></span></span> 在紧集上一致连续，故存在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0379em;">δ</span></span></span></span> 使 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">∣</span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">s</span><span class="mord">∣</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0379em;">δ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">⇒</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">∥</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.046em;">ξ</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6887em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">∗</span></span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.046em;">ξ</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6887em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">∗</span></span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal">s</span><span class="mclose">)</span><span class="mord">∥</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">ϵ</span><span class="mord">/2</span></span></span></span>；把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mclose">]</span></span></span></span> 切成长度小于 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mop">min</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0379em;">δ</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">ma</span><span class="mord mathnormal mtight">x</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 的区间，每段配一条「从 A 移到 B」的局部意图，由假设它落在某个原语模板上并能被生成器实现到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">ϵ</span><span class="mord">/2</span></span></span></span> 精度，逐段拼接即得。</p><p>真正有意思的是随后的基数讨论：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">∣</span><span class="mord mathcal" style="margin-right:0.2542em;">T</span><span class="mord">∣</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span></span></span></span> 有限，长度 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span> 的组合至多 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8413em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0715em;">K</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span></span></span></span></span></span></span></span> 种，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathcal" style="margin-right:0.0583em;">C</span><span class="mopen">(</span><span class="mord mathcal" style="margin-right:0.2542em;">T</span><span class="mclose">)</span></span></span></span> 是可数集，而 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathcal">M</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.1389em;">T</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0785em;">X</span><span class="mclose">)</span></span></span></span> 的基数是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8491em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8491em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mtight">ℵ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3173em;"><span style="top:-2.357em;margin-left:0em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.143em;"><span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span></span>。可数集稠密于不可数空间，类比于 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8556em;vertical-align:-0.1667em;"></span><span class="mord mathbb">Q</span></span></span></span> 稠密于 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6889em;"></span><span class="mord mathbb">R</span></span></span></span>。这给「学 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0715em;">K</span></span></span></span> 个原语就能覆盖行为空间的稠密子集」提供了一个干净的说法。需要注意：稠密性只保证任意轨迹可被逼近，不保证逼近所需的组合长度 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span> 有界，也不保证真实机器人能在误差累积下走完这个组合——这是论证与工程之间的缝隙。</p><p>组合泛化的机制则用 EBM 视角解释：能量可加分解 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="mopen">(</span><span class="mord mathbf">x</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0497em;vertical-align:-0.2997em;"></span><span class="mop"><span class="mop op-symbol small-op" style="position:relative;top:0em;">∑</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.162em;"><span style="top:-2.4003em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2997em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathbf">x</span><span class="mpunct">;</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">ϕ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>，每一项对应一个语义因子（物体、动作、空间关系）；扩散模型学的是 score <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord">∇</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1611em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathbf mtight">x</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord mathbf">x</span><span class="mclose">)</span></span></span></span>，隐式定义了 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">E</span><span class="mopen">(</span><span class="mord mathbf">x</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">−</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">p</span><span class="mopen">(</span><span class="mord mathbf">x</span><span class="mclose">)</span></span></span></span>，因而具备同样的模块结构，训练中分离出现的 &quot;pick&quot; 与 &quot;jar&quot; 可以在生成时重组。这是解释而非证明。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>仿真里能否超过长 horizon 的世界模型？</strong> RLBench 9 个任务、每任务 100 episode，与 Image-BC、UniPi、4DWM 对比（后三者数值引自 4DWM 论文）。本文在多数任务上最高：93 / 84 / 43 / 78 / 72 / 63 / 67 / 58 / 56，4DWM 为 88 / 80 / 44 / 70 / 70 / 56 / 73 / 62 / 41。在旋转密集的任务上略逊，作者补做了一个实验：加 100 条旋转演示按 1:5 混入轻量微调后，open jar 从 43 升到 56（此前 SOTA 54），lid off 从 67 升到 75（此前 73），而 close box、put knife 只掉 1–2 个点。</p><p><strong>真机上零样本可用吗？</strong> 三个真实任务与 OpenVLA 对比：pick up cup 规划 18/20、帧真实性 17/20、任务成功 16/20，OpenVLA 微调后 12/20、零样本 0/20；move cloth 16/15/14 对 10/20 与 0/20；fold cloth 15/14/13 对 4/20 与 0/20。</p><p><strong>组合泛化是真的吗？</strong> 对未见的（谓词，物体）配对做真机测试：pick 行 9/10、8/10、8/10，open 行 9/10、9/10、7/10，push 行 7/10、8/10、8/10、6/10。其中 &quot;pick jar&quot; 80%、&quot;open cup&quot; 70% 是训练中未出现的组合。</p><p><strong>哪个组件在起作用？</strong> 消融（每设置 20 次）：完整 16/14/13；去掉 SGG 降到 12/10/7；去掉原语规划器（指令直接映射动作）降到 9/5/3；去掉仿真数据降到 12/9/5。结论是原语分解 &gt; 空间接地 &gt; 仿真数据。</p><p><strong>生成质量与效率</strong>：32 帧序列上 SSIM 0.8126、PSNR 21.0644，优于 TesserAct（CogVideoX 5B）的 0.8034 / 20.0823 与 Hunyuan I2V（13B）的 0.7767 / 18.4264；作者自建的 EPiCS 物理一致性人评（13 分制，Fleiss <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">κ</span></span></span></span> = 0.78）得 11.45，高于 TesserAct 10.15、Hunyuan 9.65、Wan2.1 I2V 5.00。效率上 32 帧约 16 秒、约 11 GB 显存，对比 4DWM 的 0.045 FPS / 20 GB 与 Wan2.1 I2V 的 0.03 FPS / 76.7 GB。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句版</strong>：具身世界模型的瓶颈是语言与动作的对齐粒度，而非模型容量；把生成窗口限制到语义原子（约 2 秒）能同时改善对齐、复杂度、采集效率与延迟；一次长程演示按原语切开可放大数倍样本量，配合多视角同步与 VLM 自动标注可再放大一个量级；起止点热力图提供的显式空间接地是成功率的关键（去掉后成功率从 16/20 掉到 12/20）；长程能力交给 VLM 规划器串接原语，比让单一模型端到端预测长视频更稳。</p><p><strong>3 句版</strong>：短窗口 + 显式空间接地让 1.4B 的视频模型精确到可以直接用 Gen6D 抽 6-DoF 轨迹，不需要额外的策略头或 IK 模块。组合泛化来自扩散模型的因子化先验加上规划器的语义接地，未见的（动作，物体）配对可达 70–90% 成功率。仿真与真实混合的三阶段课程解决了纯真数据下夹爪等快速运动部件模糊的问题。</p><p><strong>1 句版</strong>：把世界模型从「预测长远未来的大脑」改造成「预测下一步的小脑」，长程留给 VLM 去拼。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最关键的是 <strong>Assumption 2.2：任何长程具身任务都可以分解为有限条满足定义 2.1 的原语序列，且这些原语可以直接拼接执行</strong>。整篇论文的稠密性定理、数据放大、组合泛化、长程执行全部建立在它之上；它若不成立，核心贡献同时失效。</p><p>它在实践中的脆弱之处在于「可拼接」这三个字。原语被定义为语义不可分且时长受限，但真实操作里存在大量<strong>跨原语的连续约束</strong>：倒水时手腕角度必须在整个过程中维持，擦拭时的接触力必须连续，双臂协作时两条臂的相位必须耦合。把这类任务切成 2 秒片段，切口处的状态（速度、接触力、腕部角度）并不在观测图像里，而模型只以「当前帧 + 热力图」为条件，切口必然丢信息。</p><p>论文提供的证据是：闭环回灌最新帧可以修正漂移；真机三个任务成功率 13–16 / 20。缺的证据是<strong>对拼接失败本身的分析</strong>——4 到 7 次失败中有多少发生在原语交界处？论文没有给出失败模式的分解。此外，作者在结论中把「双臂、可形变物体、多智能体」列为未来工作，恰好都是拼接假设最可能失效的场景，这可以推断为作者自己也意识到了这条边界。</p><p>另有一处内部张力值得记录：正文称因果蒸馏后可达 12 FPS 在线预测，而附录 H.4/H.5 的效率与延迟分析显示 32 帧约 16 秒（2.0 FPS）、单原语扩散 rollout 约 15.7 秒。作者说明后者是未优化实现，是延迟上界。两个数字对应不同配置，读者需要分开理解。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做的最小验证，目标是隔离「短窗口 + 空间接地」的贡献，不必建真机平台：</p><ul><li>数据：只用 LIBERO 或 RLBench 的公开演示，用固定规则（夹爪开合事件）自动切分成短片段作为原语，取 3 个任务、每任务 100 条。</li><li>实现：微调一个小 I2V 模型（DynamiCrafter 或同级），三个 arm——(a) 长 horizon：一条完整任务一段视频；(b) 短 horizon 无热力图；(c) 短 horizon + 起止点热力图（可由演示中夹爪真值位置直接生成，跳过 VLM Grounder）。</li><li>测量：在留出初始状态上生成 rollout，用同一个现成 6D 位姿估计器抽末端轨迹，与真值轨迹算末端位置 RMSE 与终点误差；同时记录仿真中回放该轨迹的成功率。</li><li>判据：若 (c) 明显优于 (b)，说明 SGG 的收益可复现；若 (b) 已明显优于 (a)，说明「缩短窗口」本身就是主因，与规划器无关。这直接对应论文消融中最大的两个 gap。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p><strong>替代解释</strong>：本文相对 4DWM、UniPi 的优势可能主要来自<strong>任务被切碎后每次预测都更容易</strong>，而不是学到了更好的世界模型。一个短窗口模型只需预测 2 秒内的运动趋势，误差自然更小；而所有真正的困难都被推给了 VLM 规划器与闭环重规划——每执行完一个原语就重新看一次世界，本质上是用高频重规划掩盖模型的预测误差。要检验这一点，可以固定原语切分与规划器，只把世界模型换成长 horizon 版本但同样每 2 秒重规划一次；若两者成功率接近，那么「原语级世界模型」的贡献就退化为「高频闭环」的贡献。</p><p><strong>可预测的失败条件</strong>：需要跨原语维持隐状态的任务。具体设计——(1) 倒水：杯中液面高度与腕部角度必须连续，切口处丢失；(2) 拉拉链或擦桌：接触力需全程维持，视觉观测无法恢复；(3) 长程回访：把杯子放到抽屉再取回，要求模型记住抽屉里的状态。论文的三个真机任务（拿杯、移布、叠布）都不涉及这类连续隐状态。此外，附录 B.2 已经暴露了动作提取链路的脆弱性：相机与主运动平面垂直时 Gen6D 成功率降到 7/10，深度位移小于 15 像素直接失败——这意味着方法对相机摆位有隐含要求，而这一点在系统级评测里没有被计入。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：原语之间的接口目前只有「一张 RGB 帧」。所有非视觉的连续状态——接触力、速度、腕部姿态、被操作物的内部状态——在切口处全部丢失，这既限制了可处理的任务类型，也使误差在拼接处累积。</p><p><strong>新的 framing</strong>：把原语从「一段视频」升级为「带类型化前置条件与后置效果的接口对象」，即为每条原语学习一个紧凑的<strong>状态承载向量</strong>，它在原语结束时被写出、在下一条原语开始时被读入，与 RGB 帧一起作为生成条件。这不是加一个模块，而是改变原语的定义：原语不再是自足的视频片段，而是带签名的可组合算子。</p><p><strong>可借鉴的相邻领域工具</strong>：程序语言里的类型系统与契约（前置/后置条件）给出了「什么样的原语可以接在什么后面」的形式化；经典 TAMP（任务与运动规划）里的符号-连续接口已经处理过同样的问题；RNN/SSM 的隐状态传递给出了学习这种承载向量的现成机制。</p><p><strong>第一个实验</strong>：构造一个必须跨原语传状态的最小任务——倒水，把它切成「抓杯 → 移动 → 倾倒 → 回正」四条原语。对比两种设置：(a) 原语间只传 RGB 帧（本文）；(b) 额外传一个 16 维学习得到的承载向量（用真实的液面高度与腕部角度做辅助监督）。度量倾倒阶段的洒出量与终点液面误差。若 (b) 显著更好，就说明原语接口的贫瘠是当前范式的真实瓶颈，「原语 = 短视频」应当被「原语 = 带签名的算子」取代；若无差别，则说明 RGB 帧在这类任务上已经充分，短窗口范式的边界比预期更宽。</p>',53)])])}const d=a(l,[["render",e]]);export{o as __pageData,d as default};
